text:
Cada producto (fila del COU) y cada actividad (columna) tiene una sola categoría, válida para todos los años en que INDEC publica su código. Elija un año para ver qué códigos existen, cuánto pesan en la producción y a qué categoría pertenecen.
Para cambiar categorías y ver qué pasa con los agregados, use la herramienta de bioeconomía: el mismo mosaico, con un clic para reclasificar.


P = transpose(prod)
A = transpose(act)
W = transpose(pesos)
C = transpose(cats)
ANIOS = typeof anios === "number" ? [anios] : anios
fmtPct = (x) =&gt; x == null ? "–" : (x * 100).toLocaleString("es-AR", {minimumFractionDigits: 1, maximumFractionDigits: 1}) + " %"

function segmented(opciones, valor, etiqueta) {
  const el = html`&lt;div class="seg" role="radiogroup" aria-label=${etiqueta}&gt;&lt;/div&gt;`;
  el.value = valor;
  const botones = opciones.map(o =&gt; {
    const b = html`&lt;button type="button" role="radio"&gt;${o}&lt;/button&gt;`;
    const marcar = () =&gt; botones.forEach(([x, v]) =&gt; { x.classList.toggle("on", v === el.value); x.setAttribute("aria-checked", v === el.value); });
    b.addEventListener("click", () =&gt; { el.value = o; marcar(); el.dispatchEvent(new Event("input", {bubbles: true})); });
    el.append(b);
    return [b, o];
  });
  botones.forEach(([x, v]) =&gt; { x.classList.toggle("on", v === valor); x.setAttribute("aria-checked", v === valor); });
  return el;
}

function chips(cs) {
  const el = html`&lt;div class="chips" aria-label="Categorías"&gt;&lt;/div&gt;`;
  el.value = cs.map(c =&gt; c.cat);
  const bs = cs.map(c =&gt; {
    const b = html`&lt;button type="button" aria-pressed="true"&gt;&lt;i&gt;&lt;/i&gt;${c.nombre}&lt;/button&gt;`;
    b.className = "chip on c" + c.cat;
    b.addEventListener("click", () =&gt; {
      const on = !b.classList.contains("on");
      b.classList.toggle("on", on); b.setAttribute("aria-pressed", on);
      el.value = cs.filter((_, k) =&gt; bs[k].classList.contains("on")).map(x =&gt; x.cat);
      el.dispatchEvent(new Event("input", {bubbles: true}));
    });
    el.append(b);
    return b;
  });
  return el;
}

function buscador() {
  const el = html`&lt;label class="buscar"&gt;&lt;span class="sr-only"&gt;Buscar&lt;/span&gt;&lt;input type="search" placeholder="Buscar: carne, 1514, papel…" autocomplete="off"&gt;&lt;/label&gt;`;
  const inp = el.querySelector("input");
  el.value = "";
  inp.addEventListener("input", (e) =&gt; { e.stopPropagation(); el.value = inp.value; el.dispatchEvent(new Event("input", {bubbles: true})); });
  return el;
}


































































viewof anio = segmented(ANIOS, ANIOS[ANIOS.length - 1], "Año")







