viewof q = buscador()








norm = (s) =&gt; (s ?? "").toString().normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase()
vigente = (d) =&gt; d.desde &lt;= anio && (d.hasta == null || d.hasta &gt;= anio)
peso = (tipo, cod) =&gt; W.find(w =&gt; w.tipo === tipo && w.cod === cod && w.anio === anio)?.s ?? 0
conPeso = (L, tipo) =&gt; L.filter(vigente).map(d =&gt; ({...d, s: peso(tipo, d.cod), nuevo: d.desde === anio && anio &gt; ANIOS[0]}))
Pv = conPeso(P, "p")
Av = conPeso(A, "a")
coincide = (d) =&gt; filtro.includes(d.cat) && (q === "" || norm(d.cod + " " + d.completo + " " + d.grupo).includes(norm(q)))



















































resumen = {
  const fila = (L) =&gt; C.map(c =&gt; {
    const xs = L.filter(d =&gt; d.cat === c.cat);
    return {...c, n: xs.length, s: xs.reduce((a, d) =&gt; a + d.s, 0)};
  });
  const rp = fila(Pv), ra = fila(Av);
  const barra = (r, titulo) =&gt; html`&lt;div class="barra-res"&gt;
    &lt;div class="barra-t"&gt;${titulo}&lt;/div&gt;
    &lt;div class="barra" role="img" aria-label=${titulo + ": " + r.map(x =&gt; x.nombre + " " + fmtPct(x.s)).join(", ")}&gt;
      ${r.map(x =&gt; html`&lt;div class="seg-b c${x.cat}" style=${"flex-grow:" + x.s} title=${x.nombre + ": " + fmtPct(x.s)}&gt;&lt;/div&gt;`)}
    &lt;/div&gt;&lt;/div&gt;`;
  return html`&lt;div class="tarjetas"&gt;
    ${C.map((c, i) =&gt; html`&lt;div class="tarjeta c${c.cat}"&gt;
      &lt;div class="t-nombre"&gt;&lt;i&gt;&lt;/i&gt;${c.nombre}&lt;/div&gt;
      &lt;div class="t-cifras"&gt;
        &lt;div&gt;&lt;span class="t-n"&gt;${rp[i].n}&lt;/span&gt;&lt;span class="t-l"&gt;productos&lt;/span&gt;&lt;span class="t-p"&gt;${fmtPct(rp[i].s)} de la producción&lt;/span&gt;&lt;/div&gt;
        &lt;div&gt;&lt;span class="t-n"&gt;${ra[i].n}&lt;/span&gt;&lt;span class="t-l"&gt;actividades&lt;/span&gt;&lt;span class="t-p"&gt;${fmtPct(ra[i].s)} de la producción&lt;/span&gt;&lt;/div&gt;
      &lt;/div&gt;
      &lt;div class="t-scn"&gt;SCN 2025: ${c.scn.toLowerCase()}&lt;/div&gt;
    &lt;/div&gt;`)}
  &lt;/div&gt;
  &lt;div class="barras"&gt;${barra(rp, "Producción por categoría del producto, " + anio)}${barra(ra, "Producción por categoría de la actividad, " + anio)}&lt;/div&gt;`;
}







function mosaico(L, etiquetaGrupo) {
  const vis = L.filter(coincide);
  if (!vis.length) return html`&lt;p class="vacio"&gt;Ningún código coincide con la búsqueda y las categorías elegidas.&lt;/p&gt;`;
  const max = Math.max(...L.map(d =&gt; d.s), 1e-9);
  const grupos = d3.groups(vis.sort((a, b) =&gt; a.og - b.og || a.cod.localeCompare(b.cod, "es", {numeric: true})), d =&gt; d.grupo);
  return html`&lt;div class="mosaico"&gt;${grupos.map(([g, xs]) =&gt; {
    const tot = L.filter(d =&gt; d.grupo === g);
    return html`&lt;section class="grupo"&gt;
      &lt;header&gt;&lt;h4&gt;${g}&lt;/h4&gt;&lt;span class="g-n"&gt;${xs.length} de ${tot.length} ${etiquetaGrupo}&lt;/span&gt;
        &lt;span class="g-mini"&gt;${C.map(c =&gt; html`&lt;i class="c${c.cat}" style=${"flex-grow:" + tot.filter(d =&gt; d.cat === c.cat).length}&gt;&lt;/i&gt;`)}&lt;/span&gt;
      &lt;/header&gt;
      &lt;div class="tiles"&gt;${xs.map(d =&gt; html`&lt;div class="tile c${d.cat}" tabindex="0"&gt;
        &lt;span class="t-cod"&gt;${d.cod}${d.nuevo ? html`&lt;b class="nuevo"&gt;nuevo&lt;/b&gt;` : ""}&lt;/span&gt;
        &lt;span class="t-nom"&gt;${d.nombre}&lt;/span&gt;
        &lt;span class="t-peso" style=${"width:" + Math.max(2, 100 * d.s / max) + "%"}&gt;&lt;/span&gt;
        &lt;span class="tip"&gt;&lt;b&gt;${d.cod}&lt;/b&gt; · ${C[d.cat - 1].nombre}&lt;br&gt;${d.completo}&lt;br&gt;
          &lt;em&gt;${fmtPct(d.s)} de la producción de ${anio} · vigente desde ${d.desde}${d.hasta ? " hasta " + d.hasta : ""}${d.serie !== d.cod ? " · serie " + d.serie : ""}&lt;/em&gt;&lt;/span&gt;
      &lt;/div&gt;`)}&lt;/div&gt;
    &lt;/section&gt;`;
  })}&lt;/div&gt;`;
}

function tabla(L, etiqueta) {
  const vis = L.filter(coincide).sort((a, b) =&gt; b.s - a.s);
  const max = Math.max(...L.map(d =&gt; d.s), 1e-9);
  return html`&lt;div class="tabla-scroll"&gt;&lt;table class="cou clasif-tabla"&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th class="izq"&gt;Código&lt;/th&gt;&lt;th class="izq"&gt;${etiqueta}&lt;/th&gt;&lt;th class="izq"&gt;Grupo&lt;/th&gt;&lt;th class="izq"&gt;Categoría&lt;/th&gt;&lt;th&gt;Peso en la producción, ${anio}&lt;/th&gt;&lt;th&gt;Vigencia&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${vis.map(d =&gt; html`&lt;tr&gt;
      &lt;td class="izq cod"&gt;${d.cod}&lt;/td&gt;&lt;td class="izq nom"&gt;${d.completo}&lt;/td&gt;&lt;td class="izq"&gt;${d.grupo}&lt;/td&gt;
      &lt;td class="izq"&gt;&lt;span class="pill p${d.cat}"&gt;${C[d.cat - 1].nombre}&lt;/span&gt;&lt;/td&gt;
      &lt;td class="peso"&gt;&lt;span class="mini-barra"&gt;&lt;i class="c${d.cat}" style=${"width:" + (100 * d.s / max) + "%"}&gt;&lt;/i&gt;&lt;/span&gt;${fmtPct(d.s)}&lt;/td&gt;
      &lt;td&gt;${d.desde}${d.hasta ? "–" + d.hasta : "–"}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;`;
}
















